<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { ApiError } from '@/api/client'; import { getSource, updateSource, updateSourceContent, type SourceDetail } from '@/api/sources'; import { getSession } from '@/api/session'; import VisualMarkdownEditor from '@/components/VisualMarkdownEditor.vue';
const route = useRoute(); const router = useRouter(); const data = ref<SourceDetail | null>(null); const loading = ref(true); const form = ref({ nombre: '', description: '', content: '' }); const error = ref<string | null>(null); const message = ref<string | null>(null); const saving = ref(false); const id = () => String(route.params.source);
const load = async () => { loading.value = true; error.value = null; try { const session = await getSession(); if (session.active_role?.code !== 'coordinador') { await router.replace('/panel'); return; } data.value = await getSource(id()); form.value = { nombre: data.value.source.name, description: data.value.source.description ?? '', content: data.value.source.content ?? '' }; } catch (reason) { error.value = reason instanceof ApiError ? reason.message : 'No se pudo cargar la fuente.'; } finally { loading.value = false; } };
const save = async () => { try { saving.value = true; error.value = null; const metadata = await updateSource(id(), { nombre: form.value.nombre, description: form.value.description || undefined }); const content = await updateSourceContent(id(), form.value.content); message.value = `${metadata.message} ${content.message}`; await load(); } catch (reason) { error.value = reason instanceof ApiError ? reason.message : 'No se pudo guardar la fuente.'; } finally { saving.value = false; } };
onMounted(() => { void load(); });
</script>
<template><main class="app-page"><header class="app-header"><div><p class="eyebrow">Coordinación</p><h1>{{ data?.source.name ?? 'Fuente académica' }}</h1><p>La IA citará extractos de este documento, no una versión posterior.</p></div><RouterLink class="back-link" to="/coordinacion/fuentes">Volver a fuentes</RouterLink></header><p v-if="data?.processLock" role="alert">{{ data.processLock }}</p><p v-if="message" class="save-status">{{ message }}</p><p v-if="error" role="alert">{{ error }}</p><p v-if="loading && !data" role="status">Cargando fuente…</p><form v-if="data" class="detail-card editor-form" @submit.prevent="save"><label>Nombre<input v-model="form.nombre" required maxlength="180" :disabled="Boolean(data.processLock)" /></label><label>Descripción<textarea v-model="form.description" maxlength="2000" :disabled="Boolean(data.processLock)" /></label><div><span class="field-label">Contenido del documento</span><VisualMarkdownEditor v-model="form.content" label="Contenido del documento" :disabled="Boolean(data.processLock)" /></div><button :disabled="saving || Boolean(data.processLock)">{{ saving ? 'Guardando…' : 'Guardar fuente' }}</button></form></main></template>
